380		expectCorruptLoad(t, dir, id, "r-bad")
381	}
382	
383	// 没有检查说明的布尔型报告，证据必须等于自动生成值。
384	func TestLoadReportRejectsEvidenceNotMatchingAutogen(t *testing.T) {
385		dir := t.TempDir()
386		hash := ArtifactHash(sampleArtifact())
387		report := Report{
388			Artifact: ReportArtifact{Name: "Vault", Hash: hash},
389			Rules: []ReportRule{
390				{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: StatusDefect},
391			},
392			Findings: []ReportFinding{
393				{ArtifactHash: hash, RuleID: "r1", Version: "1", Severity: "high", Invariant: "inv", Evidence: "invariant inv does not hold"},
394			},
395		}
396		id := storeAndCorrupt(t, dir, report, func(stored *Report) {
397			stored.Findings[0].Evidence = "hand-written claim"
398		})
399		expectCorruptLoad(t, dir, id, "r1")
400	}
401	
402	// 布尔型报告把自动证据里的不变式名写错，同样拒绝。
403	func TestLoadReportRejectsAutogenEvidenceWrongInvariant(t *testing.T) {
404		dir := t.TempDir()
405		hash := ArtifactHash(sampleArtifact())
406		report := Report{
407			Artifact: ReportArtifact{Name: "Vault", Hash: hash},
408			Rules: []ReportRule{
409				{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1", Status: StatusDefect},
410			},
411			Findings: []ReportFinding{
412				{ArtifactHash: hash, RuleID: "r1", Version: "1", Severity: "high", Invariant: "inv", Evidence: "invariant inv does not hold"},
413			},
414		}
415		id := storeAndCorrupt(t, dir, report, func(stored *Report) {
416			stored.Findings[0].Evidence = "invariant other-inv does not hold"
417		})
418		expectCorruptLoad(t, dir, id, "r1")
419	}
420	
421	// --- 关键保障：拒绝发生时 id 仍与内容相符，不依赖标识不匹配 ---
422	
423	func TestLoadReportCorruptDespiteMatchingID(t *testing.T) {
424		dir := t.TempDir()
425		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
426			stored.Findings = nil // defect rule with no finding
427		})
428		// 直接验证：归档内 reportId、请求 id、重算内容 id 三者一致，
429		// 排除“靠 id 不匹配才发现问题”。
430		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
431		if err != nil {
432			t.Fatal(err)
433		}
434		var onDisk Report
435		if err := json.Unmarshal(data, &onDisk); err != nil {
436			t.Fatal(err)
437		}
438		if onDisk.ReportID != id || ReportID(onDisk) != id {
439			t.Fatalf("test setup: id must match corrupt content, onDisk=%q recomputed=%q requested=%q", onDisk.ReportID, ReportID(onDisk), id)
440		}
441		expectCorruptLoad(t, dir, id, "r-bad")
442	}
443	
444	// --- 拒绝时不返回部分有效报告，也不自动删除/修复归档 ---
445	
446	func TestLoadReportFailureReturnsNoPartialReport(t *testing.T) {
447		dir := t.TempDir()
448		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
449			stored.Findings[0].Version = "9.9.9"
450		})
451		loaded, err := LoadReport(dir, id)
452		if err == nil {
453			t.Fatalf("expected rejection, got %+v", loaded)
454		}
455		if !reflect.DeepEqual(loaded, Report{}) {
456			t.Fatalf("failed read must return the zero report, got %+v", loaded)
457		}
458	}
459	
460	func TestLoadReportDoesNotDeleteOrRepairCorruptArchive(t *testing.T) {
461		dir := t.TempDir()
462		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
463			stored.Findings = append(stored.Findings, stored.Findings[0])
464		})
465		path := filepath.Join(dir, id+".json")
466		before, err := os.ReadFile(path)
467		if err != nil {
468			t.Fatal(err)
469		}
470		for i := 0; i < 2; i++ {
471			if _, err := LoadReport(dir, id); err == nil {
472				t.Fatal("expected corrupt rejection on repeated reads")
473			}
474		}
475		after, err := os.ReadFile(path)
476		if err != nil {
477			t.Fatalf("corrupt archive must not be deleted: %v", err)
478		}
479		if string(after) != string(before) {
480			t.Fatal("failed read must not rewrite or repair the archive")
481		}
482	}
483	
484	// 成功读取同样不得改写归档。
485	func TestLoadReportSuccessDoesNotModifyArchive(t *testing.T) {
486		dir := t.TempDir()
487		id := writeReportWithFreshID(t, dir, oneDefectFixture())
488		path := filepath.Join(dir, id+".json")
489		before, err := os.ReadFile(path)
490		if err != nil {
491			t.Fatal(err)
492		}
493		if _, err := LoadReport(dir, id); err != nil {
494			t.Fatal(err)
495		}
496		after, err := os.ReadFile(path)
497		if err != nil {
498			t.Fatal(err)
499		}
500		if string(after) != string(before) {
501			t.Fatal("successful read must not rewrite the archive")
502		}
503	}
504	
505	// 损坏拒绝不得创建任何额外的存储文件（读取路径只读）。
506	func TestLoadReportFailureCreatesNoFiles(t *testing.T) {
507		dir := t.TempDir()
508		id := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
509			stored.Findings[0].Invariant = "other-inv"
510		})
511		before, err := os.ReadDir(dir)
512		if err != nil {
513			t.Fatal(err)
514		}
515		if _, err := LoadReport(dir, id); err == nil {
516			t.Fatal("expected corrupt rejection")
517		}
518		after, err := os.ReadDir(dir)
519		if err != nil {
520			t.Fatal(err)
521		}
522		if len(after) != len(before) {
523			t.Fatalf("failed read changed file count: %d -> %d", len(before), len(after))
524		}
525	}
526	
527	// --- 错误三分类：损坏 ≠ 不存在 ≠ 请求标识不合法 ---
528	
529	func TestLoadReportErrorClassificationDistinct(t *testing.T) {
530		dir := t.TempDir()
531	
532		// 1) 损坏归档
533		corruptID := storeAndCorrupt(t, dir, oneDefectFixture(), func(stored *Report) {
534			stored.Findings = nil
535		})
536		if _, err := LoadReport(dir, corruptID); err == nil {
537			t.Fatal("expected corrupt error")
538		} else {
539			var ec errCorrupt
540			if !errors.As(err, &ec) {
541				t.Fatalf("corrupt archive -> expected errCorrupt, got %T: %v", err, err)
542			}
543		}
544	
545		// 2) 报告不存在（标识合法但无文件）
546		missing := strings.Repeat("0", 64)
547		if _, err := LoadReport(dir, missing); err == nil {
548			t.Fatal("expected not found error")
549		} else {
550			var enf errNotFound
551			if !errors.As(err, &enf) {
552				t.Fatalf("missing report -> expected errNotFound, got %T: %v", err, err)
553			}
554		}
555	
556		// 3) 请求标识不合法（根本不进存储查找）
557		for _, bad := range []string{"", "xyz", strings.Repeat("G", 64), strings.Repeat("0", 63)} {
558			if _, err := LoadReport(dir, bad); err == nil {
559				t.Fatalf("id %q: expected error", bad)
560			} else {
561				var ei errInvalid
562				if !errors.As(err, &ei) {
563					t.Fatalf("id %q: expected errInvalid, got %T: %v", bad, err, err)
564				}
565			}
566		}
567	}
