	} {
		_, _, invariants, _, err := ParseAuditInput([]byte(input))
		if err != nil {
			t.Fatalf("absent/empty/null invariants field must be accepted: %v (input %s)", err, input)
		}
		if len(invariants) != 0 {
			t.Fatalf("want no invariant results, got %+v (input %s)", invariants, input)
		}
	}
}

